(7541347, 1207024, 38032, '<td valign="top">Love the straight-on shot and low-contrast treatment. In my top 5.</td>', 'Love the straight-on shot and low-contrast treatment. In my top 5.', '2017-10-29 11:03:02.000000', NULL, 1),
(7541349, 1206652, 38032, '<td valign="top">lovely HDR. The antenna area got a bit over-treated but still my top choice.</td>', 'lovely HDR. The antenna area got a bit over-treated but still my top choice.', '2017-10-29 11:03:47.000000', NULL, 1),
(7541352, 1206652, 23394, '<td valign="top">this works, but could use a little more finesse on the post-processing (check the shadow spread on the antenna and the hallowing on the roof lines). could possibly have used a little less foreground, but all the same, nice find.</td>', 'this works, but could use a little more finesse on the post-processing (check the shadow spread on the antenna and the hallowing on the roof lines). could possibly have used a little less foreground, but all the same, nice find.', '2017-10-29 11:07:45.000000', NULL, 1),
(7541355, 1206865, 23394, '<td valign="top">lovely image, but not a fan of the toning. just a bit too unnatural.</td>', 'lovely image, but not a fan of the toning. just a bit too unnatural.', '2017-10-29 11:10:42.000000', NULL, 1),
(7541360, 1206808, 23394, '<td valign="top">nice find. however, in my subjective opinion, another opportunity done in by too much post-processing...</td>', 'nice find. however, in my subjective opinion, another opportunity done in by too much post-processing...', '2017-10-29 11:19:25.000000', NULL, 1),
